package com.vandorlabs.neoforge.ramp;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.material.Fluids;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Real staged source snapshots, asynchronous WAL, prepared bodies and complete-process recovery. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRampAssemblyJournalChecks {
 private static final BlockPos ROOT=new BlockPos(23600,100,23600),A=ROOT.north(),B=ROOT.north(2);private static NativeRampBlock rootBlock;private static NativeRampPartBlock proxy;private static BlockEntityType<NativeRampEntity> roots;private static BlockEntityType<NativeRampPartEntity> parts;
 private static ServerLevel world;private static ServerPlayer actor;private static NativeRampEntity owner;private static NativeRampCapture.Plan capture;private static NativeRampJournal.Operation operation;private static Set<BlockPos> potential;private static int phase,ticks,checks;private static String mode;private static boolean observing,throwObserver,factoryMissing;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-assembly-journal-");}
 private static final class Part extends NativeRampPartEntity {Part(BlockPos p,BlockState s){super(parts,p,s);}@Override public void setChanged(){if(observing){for(var pos:List.of(A,B)){var other=world.getBlockEntity(pos);need(other instanceof NativeRampPartEntity part&&part.publication()!=null&&part.belongs(operation.id(),ROOT),"every prepared owner precedes first change observer");need(!((NativeRampPartEntity)other).getUpdateTag(world.registryAccess()).toString().contains("PrivateOriginal"),"observer projection excludes source snapshot");}if(throwObserver)throw new IllegalStateException("fixture prepared observer failure");}super.setChanged();}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{rootBlock=new NativeRampBlock(BlockBehaviour.Properties.of(),()->roots);proxy=new NativeRampPartBlock(BlockBehaviour.Properties.of(),()->parts);h.register(ResourceLocation.parse("vandorlabs:ramp_assembly_journal_root"),rootBlock);h.register(ResourceLocation.parse("vandorlabs:ramp_assembly_journal_part"),proxy);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{roots=BlockEntityType.Builder.<NativeRampEntity>of((p,s)->new NativeRampEntity(roots,p,s,false),rootBlock).build(null);parts=BlockEntityType.Builder.<NativeRampPartEntity>of((p,s)->factoryMissing?null:new Part(p,s),proxy).build(null);h.register(ResourceLocation.parse("vandorlabs:ramp_assembly_journal_root"),roots);h.register(ResourceLocation.parse("vandorlabs:ramp_assembly_journal_part"),parts);});}}
 @SubscribeEvent public static void start(ServerStartedEvent event){if(!enabled())return;world=event.getServer().overworld();mode=System.getProperty("vandorlabs.transmitterPhase").substring("ramp-assembly-journal-".length());for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var p=ROOT.offset(x*16,0,z*16);world.getChunkAt(p);world.setChunkForced(p.getX()>>4,p.getZ()>>4,true);}actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new UUID(3,5719),"RampAssembly"));actor.setPos(ROOT.getX()+.5,ROOT.getY(),ROOT.getZ()+.5);actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
  if(mode.endsWith("write")){for(int x=-3;x<=3;x++)for(int y=-4;y<=3;y++)for(int z=-4;z<=2;z++)world.setBlock(ROOT.offset(x,y,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(ROOT,rootBlock.defaultBlockState(),18);owner=(NativeRampEntity)world.getBlockEntity(ROOT);var choices=new CompoundTag();NativeRampSettings.defaults().writeChoices(choices);choices.putInt("EndOffsetHalfSteps",-4);choices.putInt("SpeedMode",0);owner.loadWithComponents(choices,world.registryAccess());for(var pos:List.of(A,B)){world.setBlock(pos,com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_SLAB.get().defaultBlockState(),18);var source=world.getBlockEntity(pos);source.getPersistentData().putString("PrivateOriginal","wet-"+pos.getZ());var fluid=(com.vandorlabs.neoforge.fluid.ContainedFluidHost)source;fluid.refreshFluidGeometry();need(com.vandorlabs.neoforge.fluid.NativeFluidWorld.set(fluid,0,new net.neoforged.neoforge.fluids.FluidStack(Fluids.WATER,1000)),"actual source owns contained water");world.setBlock(pos.west(),Blocks.STONE.defaultBlockState(),18);world.setBlock(pos.east(),Blocks.STONE.defaultBlockState(),18);}world.setBlock(B.north(),Blocks.STONE.defaultBlockState(),18);need(NativeRampAuthorization.authorize(owner,actor),"actual installed actor grant");var selected=NativeRampCapture.select(owner,actor);need(selected.accepted()&&selected.plan().sources().size()==2,"actual native source capture");capture=selected.plan();need(NativeRampClearance.inspect(owner,actor,capture,true).status()==NativeRampClearance.Status.READY,"actual full-sweep clearance");world.getServer().saveEverything(true,true,true);
  }else{owner=(NativeRampEntity)world.getBlockEntity(ROOT);need(NativeRampJournal.load(world)==NativeRampJournal.Status.READY,"startup recovery admission");operation=NativeRampJournal.atRoot(world,ROOT);if(mode.equals("abrupt-read")){need(operation!=null&&NativeRampHeldOwners.blocked(world,A),"prepared body held before gameplay after abrupt restart");phase=4;}else{need(operation==null,"completed typed publication retired");finish();}}
 }
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(world==null)return;if(++ticks>1800)throw new AssertionError("Assembly journal timeout mode="+mode+" phase="+phase+" op="+(operation==null?null:operation.phase())+" error="+(operation==null?null:operation.error()));
  if(phase==0){var initial=new NativeRampPartData.Motion(0,world.getGameTime(),0,0,8,false,0);var start=NativeRampJournal.prepareAssembly(owner,actor,capture,proxy.defaultBlockState().setValue(NativeRampPartBlock.FACING,capture.facing()),initial,NativeRampPartData.Belt.NONE);need(start.status()!=NativeRampJournal.Status.REFUSED,"typed preparation admitted "+start.error());if(start.operation()==null)return;operation=start.operation();potential=operation.assembly().potential();phase=1;}
  if(phase==1){var ready=NativeRampJournal.poll(world,operation);need(ready!=NativeRampJournal.Status.REFUSED,"async prepare "+operation.error());if(ready==NativeRampJournal.Status.PENDING)return;need(!NativeRampHeldOwners.blocked(world,A),"mere preparation remains usable");need(NativeRampJournal.arm(world,operation,actor)==NativeRampJournal.Status.PENDING,"real ARM receipt pending");phase=2;}
  if(phase==2){if(NativeRampJournal.poll(world,operation)==NativeRampJournal.Status.PENDING)return;need(operation.phase()==NativeRampJournal.Phase.ARMED,"ARM durable before source removal");if(mode.equals("factory-write"))factoryMissing=true;var assembly=operation.assembly();var riders=NativeRampRiderPlan.prepare(world,assembly.footprint(),false,0,0,true,false);need(riders!=null,"actual empty rider plan");observing=true;throwObserver=mode.equals("observer-write");var result=NativeRampJournal.applyAssembly(world,operation,actor,riders,(p,payload)->{throw new AssertionError("Unexpected player rider");});observing=false;throwObserver=false;factoryMissing=false;
   if(mode.equals("factory-write")){need(result==NativeRampJournal.Status.REFUSED&&world.getBlockEntity(A) instanceof com.vandorlabs.neoforge.shape.ProgrammableShapeEntity,"factory refusal precedes original mutation");phase=4;}
   else if(mode.equals("observer-write")){need(result==NativeRampJournal.Status.REFUSED,"caught observer refusal retains durable owner");need(NativeRampJournal.recover(world,operation)==NativeRampJournal.Status.PENDING,"immediate original restoration after publication callback failure");assertOriginals();phase=4;}
   else{need(result==NativeRampJournal.Status.PENDING,"prepared source publication awaits durable checkpoint");need(world.getBlockEntity(A) instanceof NativeRampPartEntity part&&part.publication()!=null&&part.data().original().is(com.vandorlabs.neoforge.VandorLabsBootstrap.PROGRAMMABLE_SLAB.get()),"genuine body replaces captured source");need(com.vandorlabs.neoforge.fluid.NativeFluidWorld.pickupBlock(world,A).isEmpty(),"private source water cannot be drained from generated body");phase=3;}}
  if(phase==3){var status=NativeRampJournal.poll(world,operation);need(status!=NativeRampJournal.Status.REFUSED,"typed publication checkpoint "+operation.error());if(status==NativeRampJournal.Status.PENDING)return;need(operation.phase()==NativeRampJournal.Phase.APPLIED,"durable vacated receipt");if(mode.equals("abrupt-write")){world.noSave=true;System.out.println("[vandorlabs][ramp-assembly-journal] abrupt PASS checks="+checks);System.out.flush();Runtime.getRuntime().halt(0);}phase=4;}
  if(phase==4){var status=NativeRampJournal.recover(world,operation);need(status!=NativeRampJournal.Status.REFUSED,"typed source recovery "+operation.error());if(status==NativeRampJournal.Status.DONE)finish();}
 }
 private static void assertOriginals(){for(var pos:List.of(A,B)){var source=world.getBlockEntity(pos);need(source instanceof com.vandorlabs.neoforge.shape.ProgrammableShapeEntity,"native source restored");need(source.getPersistentData().getString("PrivateOriginal").equals("wet-"+pos.getZ()),"opaque source metadata preserved");need(((com.vandorlabs.neoforge.fluid.ContainedFluidHost)source).containedFluids().get(0).getAmount()==1000,"one restored contained-water owner");}}
 private static void finish(){assertOriginals();need(!NativeRampHeldOwners.active(world),"all source/part holds retired");if(potential!=null)for(var pos:potential)need(!world.getBlockState(pos).is(proxy),"all generated bodies retired");world.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][ramp-assembly-journal] "+(mode.endsWith("write")?"write":"read")+" PASS checks="+checks);world.getServer().halt(false);world=null;}
 private static void need(boolean ok,String message){checks++;if(!ok)throw new AssertionError("Ramp assembly journal "+mode+": "+message);}
}
